621:     heist.locked = false;
622:     heist.widen = false;
623:     heist.zoneBase = Math.min(0.5, r.zone * state.plan.zone);
624:     heist.zoneFrac = heist.zoneBase;
625:     heist.half = heist.zoneFrac * 180;
626:     heist.zoneCenter = 58 + Math.random() * 244;
627:     heist.angle = (heist.zoneCenter + 150 + Math.random() * 60) % 360;
628:     heist.speed = r.speed;
629:     heist.limit = r.time;
630:     heist.startTime = performance.now();
631:     heist.last = heist.startTime;
632:     heist.slowUntil = 0;
