636:     $('#heistHint').textContent = r.hint;
637:     $('#heistMsg').textContent = '';
638:     $('#heistMsg').className = 'heist-msg';
639:     $('#gaugePop').className = 'gauge-pop';
640:     $('#gaugeFlash').className = 'gauge-flash';
641:     $('#timeBar').style.width = '100%';
642:     $('#timeBar').parentNode.classList.remove('low');
643:     $('#tapBtn').disabled = false;
644:     $('#supportBtn').classList.remove('used');
645:     updateZone();
646:     updateNeedle();
647:     updateHeistHud();
648:     Sound.ui();
649:     raf = requestAnimationFrame(loop);
