652:   function loop(now) {
653:     if (!heist || !heist.active) return;
654:     var dt = Math.min(0.06, (now - heist.last) / 1000);
655:     heist.last = now;
656:     var speed = heist.speed;
657:     if (now < heist.slowUntil) speed *= 0.42;
658:     heist.angle = (heist.angle + speed * dt) % 360;
659:     updateNeedle();
660:     var left = heist.limit - (now - heist.startTime) / 1000;
661:     var pct = clamp((left / heist.limit) * 100, 0, 100);
662:     $('#timeBar').style.width = pct + '%';
663:     $('#timeBar').parentNode.classList.toggle('low', left < 1.6);
664:     if (left <= 0) {
665:       resolveMiss(true);
666:       return;
667:     }
668:     raf = requestAnimationFrame(loop);
669:   }
