694:   function resolveHit(quality) {
695:     if (!heist) return;
696:     heist.active = false;
697:     heist.locked = true;
698:     if (raf) cancelAnimationFrame(raf);
699:     raf = null;
700:     var r = D.HEIST_ROUNDS[heist.round];
701:     heist.combo += 1;
702:     heist.maxCombo = Math.max(heist.maxCombo, heist.combo);
703:     heist.hits += 1;
704:     var mult = quality === 'perfect' ? 1.5 : quality === 'great' ? 1.25 : 1;
705:     var reward = Math.round((r.loot * state.plan.loot * mult * (1 + (heist.combo - 1) * 0.04)) / 500) * 500;
706:     heist.loot += reward;
707:     if (quality === 'perfect') heist.susp = Math.max(0, heist.susp - 4);
708:     else if (quality === 'great') heist.susp = Math.max(0, heist.susp - 2);
709:     updateHeistHud();
710: 
711:     var label = quality === 'perfect' ? 'MÜKEMMEL' : quality === 'great' ? 'HARİKA' : 'TAMAM';
712:     pop('+₺' + money(reward), label + (heist.combo > 1 ? ' · ×' + heist.combo : ''), 'hit');
713:     $('#gaugeFlash').className = 'gauge-flash hit';
714:     $('#heistMsg').textContent = r.win;
715:     $('#heistMsg').className = 'heist-msg good';
716:     timers.push(setTimeout(function () { $('#gaugeFlash').className = 'gauge-flash'; }, 500));
717:     Sound.hit(quality);
718:     vibrate(quality === 'perfect' ? [12, 30, 12] : 14);
719:     timers.push(setTimeout(nextRound, 1250));
720:   }
721: 
722:   function resolveMiss(timeout) {
723:     if (!heist || heist.locked) return;
724:     heist.active = false;
725:     heist.locked = true;
726:     if (raf) cancelAnimationFrame(raf);
727:     raf = null;
728:     var r = D.HEIST_ROUNDS[heist.round];
729:     heist.combo = 0;
730:     heist.misses += 1;
731:     var mod = state.you === 'selin' ? 0.8 : 1;
732:     var gain = 22 * state.plan.susp * mod * (1 - state.ortaklik / 400);
733:     gain = Math.max(6, Math.round(gain));
734:     heist.susp = Math.min(100, heist.susp + gain);
735:     updateHeistHud();
736:     pop(timeout ? 'ÇOK YAVAŞ' : 'ISKA', 'ŞÜPHE +' + gain, 'miss');
737:     $('#gaugeFlash').className = 'gauge-flash miss';
738:     $('#heistMsg').textContent = r.lose;
739:     $('#heistMsg').className = 'heist-msg bad';
740:     timers.push(setTimeout(function () { $('#gaugeFlash').className = 'gauge-flash'; }, 500));
741:     Sound.miss();
742:     vibrate([25, 40, 25]);
743:     timers.push(setTimeout(nextRound, 1250));
744:   }
