791:   function finish(caught) {
792:     if (!heist) return;
793:     clearTimers();
794:     if (raf) cancelAnimationFrame(raf);
795:     raf = null;
796:     heist.active = false;
797:     var stats = {
798:       kimya: Math.round(state.kimya),
799:       ortaklik: Math.round(state.ortaklik),
800:       susp: Math.round(heist.susp),
801:       hits: heist.hits,
802:       misses: heist.misses,
803:       maxCombo: heist.maxCombo,
804:       loot: heist.loot
805:     };
806:     var endingId;
807:     if (caught) endingId = 'caught';
808:     else if (heist.misses === 0 && heist.susp <= 10) endingId = 'ghost';
809:     else if (state.kimya >= 50 && state.ortaklik >= 50) endingId = 'legend';
810:     else if (state.kimya >= 50) endingId = 'love';
811:     else if (state.ortaklik >= 50) endingId = 'crew';
